// 一份很小的数学库：几个纯函数，全走 module.exports。
function sum(xs) {
  let s = 0
  for (const x of xs) s += x
  return s
}

function mean(xs) {
  if (xs.length === 0) return 0
  return sum(xs) / xs.length
// ↑ 少了这一层的右括号：现在整份文件连语法检查都过不了。

module.exports = { sum, mean }

